import{_ as d,o as r,c as a,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const b=JSON.parse('{"title":"LLMおすすめキャラ（実験）","description":"","frontmatter":{"title":"LLMおすすめキャラ（実験）","layout":"doc"},"headers":[],"relativePath":"site/ja/llm-recommend.md","filePath":"site/ja/llm-recommend.md"}'),e={name:"site/ja/llm-recommend.md"};function n(s,t,l,h,i,c){return r(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="llmおすすめキャラ" tabindex="-1">LLMおすすめキャラ <a class="header-anchor" href="#llmおすすめキャラ" aria-label="Permalink to &quot;LLMおすすめキャラ&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">実験的コンテンツ</p><p>本ページは大規模言語モデル（AI）が<strong>独自に推論</strong>した内容です。本サイトのミラーデータ（キャラ370名のステータス／必殺技／固有効果）とシステム機構の事実（ダメージ式、イントロ、必殺チェイン、装備ルール）のみを読み込み、<strong>公式レイドおすすめや公式初心者ガイドの「おすすめ名簿」は意図的に参照していません</strong>。推論は「機構の希少性 × ダメージ式の独立乗算枠 × 場持ち性能 × 完凸コスト」に基づき、あくまで参考情報として継続修正します。現在のバージョン：v0.2（2026-07-29）</p></div><h2 id="評価基準-一言" tabindex="-1">評価基準（一言） <a class="header-anchor" href="#評価基準-一言" aria-label="Permalink to &quot;評価基準（一言）&quot;">​</a></h2><p><strong>機構の希少性 × ダメージ式の独立乗算枠 × 場持ち性能 × 完凸コスト</strong>——出自や公式ランクは見ない。</p><blockquote><p>完凸ステータスは収束しており（攻撃/魔法上限521、スタミナ上限3200、防御上限500）、大半のSSRが同値。<strong>数値は差別化要因ではなく、固有効果こそが差を生む</strong>。速度バフ(126人)/充填バフ(105人)/AoE(247人)はインフレ技能であり希少価値としない。詳細は <code>llm_reco/reco-method.md</code>、<code>reasoning-log.md</code>。</p></blockquote><h2 id="一、撤退しない場持ちコア-最重要、全ゲームでわずか8名" tabindex="-1">一、撤退しない場持ちコア（最重要、全ゲームでわずか8名） <a class="header-anchor" href="#一、撤退しない場持ちコア-最重要、全ゲームでわずか8名" aria-label="Permalink to &quot;一、撤退しない場持ちコア（最重要、全ゲームでわずか8名）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キャラ</th><th>レア</th><th>推薦理由（検証済み）</th></tr></thead><tbody><tr><td>ビートソニック・アキレス</td><td>SSR</td><td>撤退しない + 体力20%未満で25~50%回復(1回)、場持ち準タンク</td></tr><tr><td>ブライドハルカ・リバース</td><td>SSR</td><td>撤退しない + 攻撃521(上限) + 即死10%(失敗で攻撃+50%まで) 、攻守一体</td></tr><tr><td>真夏のハルカ</td><td>SSR</td><td>撤退しない + 必殺スタン+50/防御+75/20%未満で必殺+50</td></tr><tr><td>閃忍マユリ</td><td>R</td><td>撤退しない + 必殺<strong>15倍 防御無視</strong>(自身に最大体力100%ダメージ)、全ゲーム最強の単体核弾、Rで入手</td></tr><tr><td>FM77</td><td>R</td><td>撤退しない（無料入手）、ゼロコストで希少な場持ち機構</td></tr><tr><td>神騎フローレル / 閃忍レイナ / 神騎プロキオン</td><td>R/SR</td><td>撤退しない、低コストな場持ち枠</td></tr></tbody></table><blockquote><p>新規は <strong>FM77 / 閃忍マユリ</strong> を優先完凸——Rコストで全ゲーム上位2%の場持ち機構を獲得。</p></blockquote><h2 id="二、顶级の希少対策-各1名のみ、sランク必見" tabindex="-1">二、顶级の希少対策（各1名のみ、Sランク必見） <a class="header-anchor" href="#二、顶级の希少対策-各1名のみ、sランク必見" aria-label="Permalink to &quot;二、顶级の希少対策（各1名のみ、Sランク必見）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キャラ</th><th>レア</th><th>推薦理由</th></tr></thead><tbody><tr><td>超昂閃忍ナリカ</td><td>SSR</td><td><strong>蘇生</strong>(火種) + 自然スタミナ減少25%停止 + 両方521/500、唯一の蘇生持ち、汎用顶级</td></tr><tr><td>体育祭のヤブルー</td><td>SSR</td><td><strong>全状態異常無効</strong>(唯一) + 出撃時全隊必殺+25% + 必殺全体魅了50%/呪縛75%、唯一の真・全無効 + 巨大なチームハードCC</td></tr><tr><td>妹の1024</td><td>SSR</td><td>通常攻撃80%でランダム味方必殺+10%(自身も同期) + 必殺 フィールド速度+30%/全隊必殺+30%(5回重ね)、最高峰の充填コア</td></tr></tbody></table><h2 id="三、希少バッファー-攻撃バフはわずか3名、魔法バフは1名" tabindex="-1">三、希少バッファー（攻撃バフはわずか3名、魔法バフは1名） <a class="header-anchor" href="#三、希少バッファー-攻撃バフはわずか3名、魔法バフは1名" aria-label="Permalink to &quot;三、希少バッファー（攻撃バフはわずか3名、魔法バフは1名）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キャラ</th><th>レア</th><th>推薦理由</th></tr></thead><tbody><tr><td>真夏のイーイー</td><td>SSR</td><td>場にいる間味方出撃で攻撃+30%(真夏は+50/速度+25) + 必殺横列6倍魔法 + 全隊スタン耐性+50、攻撃バフは3名のみの1人</td></tr><tr><td>黒門天・屍寺炎斎</td><td>SSR</td><td>体力30%/65%の2节点で毎秒5%回復+防御+100% + 必殺10倍魔法(生存で攻撃+30%最大150%)、攻撃バフは3名のみの1人</td></tr><tr><td>魔女ミヤビ</td><td>SSR</td><td>出撃時敵フィールド防速−20%(+魔女人数×10%増幅)、希少なデバフ；（信号抽出で希少攻撃/魔法バフ保持者と判定、具体的倍率は全量検証待ち）</td></tr></tbody></table><h2 id="四、無効オーラ-ヒーラー-パッシブ・消費なし、対策枠のコスパ王" tabindex="-1">四、無効オーラ + ヒーラー（パッシブ・消費なし、対策枠のコスパ王） <a class="header-anchor" href="#四、無効オーラ-ヒーラー-パッシブ・消費なし、対策枠のコスパ王" aria-label="Permalink to &quot;四、無効オーラ + ヒーラー（パッシブ・消費なし、対策枠のコスパ王）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キャラ</th><th>レア</th><th>推薦理由</th></tr></thead><tbody><tr><td>制服ニャンコ</td><td>SSR</td><td>場にいる間全隊 毒・魅了・呪縛(+/スタン)無効 + 必殺自身50%回復/全隊30%回復/全隊与ダメ+20%</td></tr><tr><td>閃忍ニャンコ</td><td>SSR</td><td>場にいる間全隊 毒・魅了・呪縛・スタン 無効 + 必殺単体味方100%回復+攻防速+30%</td></tr><tr><td>魔女フタバ</td><td>R</td><td>場にいる間全隊 毒・魅了・スタン・呪縛 無効 + 必殺横列6倍魔法、Rで全隊無効オーラ</td></tr><tr><td>六の法杖セラフィール</td><td>SSR</td><td>出撃時<strong>全隊の異常/デバフ解除</strong>(+15%回復) + フィールド毎秒5%回復、極希少なパッシブ解除ヒーラー</td></tr><tr><td>ビートプレジデント・シーラ</td><td>SSR</td><td>通常攻撃15%で必中魅了/呪縛/与ダメ−20を付与 + 必殺全隊毎秒2.5%回復</td></tr><tr><td>アイドルの奉輪こもり</td><td>SSR</td><td><strong>撤退時</strong>全隊50%回復 + 攻防+30%（死亡で全隊大回復）</td></tr><tr><td>魔女シズク</td><td>R</td><td>出撃時全隊毎秒1~2%回復 + 必殺全体2~4倍物理 + フィールド毎秒2~3%回復、安価な群療</td></tr></tbody></table><h2 id="五、防御貫通-デバフ-独立乗算枠、高防御ボスで急増" tabindex="-1">五、防御貫通 / デバフ（独立乗算枠、高防御ボスで急増） <a class="header-anchor" href="#五、防御貫通-デバフ-独立乗算枠、高防御ボスで急増" aria-label="Permalink to &quot;五、防御貫通 / デバフ（独立乗算枠、高防御ボスで急増）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キャラ</th><th>レア</th><th>推薦理由</th></tr></thead><tbody><tr><td>鬼の斗羽大洋</td><td>SSR</td><td>出撃時敵与ダメ−25%/味方+25% + 必殺<strong>全体攻防−60%</strong>、デバフ幅は希少</td></tr><tr><td>神騎ハニーエル</td><td>R</td><td>自身魔法無効 + 全隊 スタン・呪縛 無効 + 必殺蜂蜜魔免貫通、Rの魔免対策専門</td></tr><tr><td>閃忍マユリ</td><td>R</td><td>第一節参照：15倍 防御無視核弾</td></tr></tbody></table><h2 id="六、ハードcc対策-rカードの安価案" tabindex="-1">六、ハードCC対策（Rカードの安価案） <a class="header-anchor" href="#六、ハードcc対策-rカードの安価案" aria-label="Permalink to &quot;六、ハードCC対策（Rカードの安価案）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キャラ</th><th>レア</th><th>推薦理由</th></tr></thead><tbody><tr><td>エスカ・アメイズ</td><td>R</td><td>必殺 全体 <strong>必中魅了</strong>(魅了無効は対象外)</td></tr><tr><td>閃忍クサリ</td><td>R</td><td>必殺 全体 <strong>確定スタン</strong>(スタン無効は対象外) + 呪縛 + 速度−20</td></tr><tr><td>閃忍ツルコ</td><td>R</td><td>出撃時自身速度+30 + 必殺全体2~4倍物理 + スタン+50</td></tr></tbody></table><h2 id="七、初心者コア-低コスト完凸、機構基準・公式名指し不要" tabindex="-1">七、初心者コア（低コスト完凸、機構基準・公式名指し不要） <a class="header-anchor" href="#七、初心者コア-低コスト完凸、機構基準・公式名指し不要" aria-label="Permalink to &quot;七、初心者コア（低コスト完凸、機構基準・公式名指し不要）&quot;">​</a></h2><blockquote><p>鉄則：完凸★5のR ≫ 無凸★1のSSR。以下は機構が希少で完凸しやすいR/SRの起点です（v0.1の未検証「公式名指し」カードを置換）：</p></blockquote><table tabindex="0"><thead><tr><th>キャラ</th><th>レア</th><th>担う機構</th></tr></thead><tbody><tr><td>FM77</td><td>R</td><td>撤退しない（無料）</td></tr><tr><td>閃忍マユリ</td><td>R</td><td>撤退しない + 15倍 防御無視核弾</td></tr><tr><td>神騎アルゴル</td><td>R</td><td>出撃時フィールド速度+25% + 必殺全隊必殺+30%</td></tr><tr><td>神騎ハニーエル</td><td>R</td><td>魔法無効 + 全隊スタン/呪縛無効 + 魔免貫通</td></tr><tr><td>閃忍サイカ</td><td>R</td><td>出撃時<strong>敵フィールド時間停止2.5~4秒</strong>(唯一の開幕凍結) + 低速3人速度+25%</td></tr><tr><td>魔女シズク</td><td>R</td><td>安価な群療</td></tr><tr><td>エスカ・アメイズ</td><td>R</td><td>必中魅了</td></tr><tr><td>閃忍クサリ</td><td>R</td><td>確定スタン</td></tr><tr><td>魔女フタバ</td><td>R</td><td>全隊4異常無効オーラ</td></tr><tr><td>ビートアミュレット・ノノノ</td><td>R</td><td>出撃時全隊必殺+25% + 必殺全隊攻防+30/敵−30</td></tr></tbody></table><h2 id="八、編成コア-勢力バフ軸" tabindex="-1">八、編成コア（勢力バフ軸） <a class="header-anchor" href="#八、編成コア-勢力バフ軸" aria-label="Permalink to &quot;八、編成コア（勢力バフ軸）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>勢力</th><th>コア</th><th>説明</th></tr></thead><tbody><tr><td>魔女</td><td>魔女シズク(R) / 魔女ミヤビ</td><td>Rで編成コアになれる希少例</td></tr><tr><td>戦士</td><td>エスカレイヤー系</td><td>伝説の戦士+：開幕から戦士3名に強力バフ（倍率は全量検証待ち）</td></tr><tr><td>閃忍</td><td>閃忍ハルカ / 閃忍サイカ(彼岸花に+300%)</td><td>閃忍バフ + 速度軸</td></tr><tr><td>神騎</td><td>神騎エクシール / 神騎アルゴル(R)</td><td>神騎バフ + 安価充填</td></tr></tbody></table><hr><h2 id="九、編成と副本対策-v0-3-追加" tabindex="-1">九、編成と副本対策（v0.3 追加） <a class="header-anchor" href="#九、編成と副本対策-v0-3-追加" aria-label="Permalink to &quot;九、編成と副本対策（v0.3 追加）&quot;">​</a></h2><blockquote><p>レイド/副本機構と編成リレーシステムを統合（事実データ、推薦ランクではない）。詳細は <code>llm_reco/reco-team.md</code>。</p></blockquote><h3 id="重要認識-出撃5名-単独決戦" tabindex="-1">重要認識：出撃5名 ≠ 単独決戦 <a class="header-anchor" href="#重要認識-出撃5名-単独決戦" aria-label="Permalink to &quot;重要認識：出撃5名 ≠ 単独決戦&quot;">​</a></h3><p>レイドは体力が毎秒2%減（百分率、<strong>両防御無効</strong>）、単隊は約50秒で全滅 → 高得点は<strong>多隊リレー</strong>：優先1(5)→優先2(15)→控え→星面50名。「分隊」=リレー交代。編成は「先発隊+リレー隊」の構成が必要。</p><h3 id="編成鉄則" tabindex="-1">編成鉄則 <a class="header-anchor" href="#編成鉄則" aria-label="Permalink to &quot;編成鉄則&quot;">​</a></h3><ul><li><strong>防御低下デバフ ≫ 攻撃バフ</strong>：減傷75%ボスで防御低下の効果は攻撃バフの <strong>3倍</strong>。減傷低下を80%以上目標。</li><li>単体 + フィールド同名<strong>重ね掛け</strong>；同種複数は最高値のみ。</li><li>必殺<strong>充填補助=得点の核心</strong>；基本<strong>持続回復</strong>；<strong>確定点灯(BREAK)は時停より価値大</strong>。</li></ul><h3 id="汎用5名先発テンプレ" tabindex="-1">汎用5名先発テンプレ <a class="header-anchor" href="#汎用5名先発テンプレ" aria-label="Permalink to &quot;汎用5名先発テンプレ&quot;">​</a></h3><p>主火力（ブライドハルカ/O閃忍ナリカ/閃忍マユリ R）+ 生存補助（ビートアミュレット・ノノノ R/神騎アルゴル R）+ 防御低下（鬼の斗羽大洋 SSR/魔女ミヤビ）+ 回復（制服ニャンコ/六の法杖セラフィール/魔女シズク R）+ 自由枠（妹の1024 SSR/真夏のイーイー）。</p><h3 id="_7ボス対策要点" tabindex="-1">7ボス対策要点 <a class="header-anchor" href="#_7ボス対策要点" aria-label="Permalink to &quot;7ボス対策要点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ボス</th><th>必須対策</th><th>推薦キャラ（検証済み）</th></tr></thead><tbody><tr><td>古ナー</td><td>持続回復（フィールド1%/s）</td><td>制服ニャンコ / 六の法杖セラフィール</td></tr><tr><td>ウータル</td><td>全体攻撃/異常必殺で子猫処理</td><td>体育祭のヤブルー（全体魅了+呪縛）</td></tr><tr><td>堕威大仏</td><td>確定点灯（耐性無視）</td><td>エスカ・アメイズ R（必中魅了）/ 閃忍クサリ R（確定スタン）</td></tr><tr><td>大往女</td><td>呪縛無効/解除</td><td>制服ニャンコ / 魔女フタバ R / 神騎ハニーエル R</td></tr><tr><td>ヴリトラ</td><td>減速+シールド破り+居座り</td><td>減速キャラ（閃忍/魔女系）+ 超昂ナリカ（体力停止25%）</td></tr><tr><td>黄金甜心</td><td>物理隊 / 甘王子噛み装備</td><td>物理火力主体</td></tr><tr><td>狂王</td><td>全体必殺で配下処理</td><td>全体AoE火力</td></tr></tbody></table><h3 id="_370名から5名均衡チームを選ぶ方法-v0-4" tabindex="-1">370名から5名均衡チームを選ぶ方法（v0.4） <a class="header-anchor" href="#_370名から5名均衡チームを選ぶ方法-v0-4" aria-label="Permalink to &quot;370名から5名均衡チームを選ぶ方法（v0.4）&quot;">​</a></h3><p>5枠で「火力+防御低下+速度+充填+回復(生存)」最少5機能を満たす必要；1人1機能なら≥6枠&gt;上限なので、<strong>唯一の解=1人で複数機能を持つ高密度キャラを選ぶ</strong>（<code>char_data.json</code>全量に職能タグを打ち実測：3職以上46名、4職以上37名、5職以上10名）。</p><ul><li><strong>真に稀少で優先占枠すべき機能</strong>：撤退しない(8)/蘇生(1,全ゲーム唯一=O閃忍ナリカ)/防御低下(46)。</li><li><strong>ユーザーが強調する速度(126)/充填(102)は保有数十分</strong>で独立枠不要——「ついでに速度/充填も持つ」高密度キャラを選べば良い。</li><li><strong>最適均衡チーム</strong>：エスカサファイア・ムーンライズ(火力+速度+増傷) + 小鬼の斗羽大洋(防御低下+回復+免疫,1体で4職) + ダンスクイーン・ピカ(充填+速度) + O閃忍ナリカ(蘇生) + FM77(撤退しない)。</li><li><strong>初心者R/SRチーム</strong>：ビートノーブル・カノン(R) + 閃忍フクシュウチャン(SR) + ビートアミュレット・ノノノ(R) + FM77(R) + ビートアイドル・タマキ(R)——R/SRのみでも5/5カバー。</li><li>詳細手法と4チームの枠別機能は <code>llm_reco/reco-team.md</code> 2b節。</li></ul><h3 id="量化強度モデル-v0-8-raid専用・真の頻度式・実覚醒テーブル・実2装備・試験式採点" tabindex="-1">量化強度モデル v0.8（RAID専用・真の頻度式・実覚醒テーブル・実2装備・試験式採点） <a class="header-anchor" href="#量化強度モデル-v0-8-raid専用・真の頻度式・実覚醒テーブル・実2装備・試験式採点" aria-label="Permalink to &quot;量化強度モデル v0.8（RAID専用・真の頻度式・実覚醒テーブル・実2装備・試験式採点）&quot;">​</a></h3><p>満星育成が前提 → <strong>単キャラ強度は固定値</strong>として数学モデル化；推奨時は「与ダメージ・buff/debuff量」を直接算出（「点数=ダメージ、試験のよう」）。終局副本は4種（raid / B宇宙 / 広域戦 / 全域戦）あり、<strong>本モデルはraidのみ攻略</strong>、残り3モードは順次プレースホルダ。汎用モデルとするため「キャラkit＋真の戦闘詳細」以外を<strong>すべて固定定数</strong>に（R=0.50 / 連撃閾値60% / <strong>覚醒属性強化はゲーム内実テーブル準拠</strong> / <strong>装備は実運用2点</strong>）：</p><ul><li><strong>BOSS固定</strong>：機構常時発動・固定ダメージ・スタミナ-2%/s・固定防御率 R=0.50（グナガン系）</li><li><strong>キャラ固定</strong>：満星100級・覚醒+・覚醒属性強化MAX・<strong>メイン装備2点：ロケット(行動速度-50%)+ベルト(攻魔+50%)</strong>（サブ装備/ナットゥは除外——変数増、ナットゥは一部キャラのスキルと競合）</li><li><strong>覚醒属性強化（実テーブル）</strong>：行動速度 <strong>-0.1×20回=最大-2秒（フラット）、強化下限 3sec</strong>（基礎≤3sは恩恵なし）；必殺充填 <strong>+0.3×20回=最大+6pt、強化上限 15%</strong>（基礎≥15は恩恵なし）；攻/魔 +20%。上限 3s/15% は誰でも届く訳ではない——強化回数に制限あり。</li><li><strong>真の戦闘詳細</strong>（extract_chars.pyが詳細ステータスから抽出）：行動速度(秒) / 必殺充填量(%) / 連撃率(%)</li></ul><p><strong>単キャラ強度点</strong> = <code>0.70·DPS正規化 + 0.30·UTIL正規化</code>、DPSは真の頻度で算定（点数=秒間ダメージ）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>eff_speed   = max(行動速度 - 2, 3)              # 覚醒フラット減、下限3sec</span></span>
<span class="line"><span>interval     = eff_speed × (1 - ロケット50%)</span></span>
<span class="line"><span>interval_ult= interval × (1 + 連撃率)          # 連撃が必殺/通常リズムを遅くする（連撃ペナルティ）</span></span>
<span class="line"><span>充填eff     = 充填≥15 ? 原値 : min(充填+6, 15)  # 覚醒+6pt上限15%</span></span>
<span class="line"><span>必殺casts/s = (充填eff/100) / interval_ult</span></span>
<span class="line"><span>combo_mult  = 1 + Σ連撃率ⁿ×decay(n)            # 連撃追加ダメージ(暴撃なし)</span></span>
<span class="line"><span>削減係数    = 1 - 0.50×(1 - min(1, 防御低下))   # 防御低下はキャラkitのみ（§7.6）</span></span>
<span class="line"><span>基礎単撃    = 攻魔×1.20 × (1 + 攻buff + ベルト50%) × (1+与ダメup) × 削減係数</span></span>
<span class="line"><span>DPS = 基礎単撃×必殺倍率×3×撃破×必殺casts/s  +  (基礎単撃·暴撃 + 基礎単撃·(combo_mult-1))×通常頻度</span></span>
<span class="line"><span>UTIL = 100·蘇生 + 60·撤退しない + 40·免疫 + 35·回復 + 30·異常解除 + 25・硬控 + 30·減傷%</span></span></code></pre></div><p>→ 点数で <strong>T0/T1/T2/T3</strong> 分け（T0は37名、SSR35/SR1/R1）；370名実測TOP：<strong>レジェンド・ハルカ 78.9 &gt; 幻忍コテツ 75.4 &gt; 黒門天 73.0 &gt; ブライド・スバル 61.3 &gt; 真夏のハルカ 55.3</strong>——装備の防御低下30%下駄が消えた結果、<strong>kit自前の防御低下の価値が急騰</strong>（防御低下100% vs 60% = 削減係数 1.00 vs 0.80 = 25%のダメージ差、首位が交代）。<strong>連撃検証</strong>：連撃率≥60%は僅か3名、バビロニア・ニルは必殺占拠わず13.1%（通常≫必殺）で「連撃型は必殺重み低下」を確証。 <strong>チーム試験採点</strong>（4チーム・固定+7BOSS適応）：総合平均 <strong>D暴力 42,281 &gt; C居座 16,529 &gt; A最適 12,541 &gt; B初心 7,344</strong>（Dは5純火力・防御低下100%×9~×10→削減完全無効化、raw DPS 46,979で圧倒だが全体欠き→ウタル/狂王 fit 0.60/0.70）。 モデルと検証全文は <code>llm_reco/reco-team.md</code> §5 と <code>reasoning-log.md</code> §9；スクリプト <code>llm_reco/_char_score.py</code>、新キャラは <code>char_data.json</code> に追加→再実行で即採点。</p><blockquote><p>副本次元：メイン/EXは<strong>時間制限・両防御有効</strong> → 撤退しない/蘇生（O閃忍ナリカ、Bソニック・アキレス）が本領発揮；デイリー/宝箱狩りはAoE+充填で効率重視。</p></blockquote><hr><p><em>本ページはAI独自実験ページであり、サイトナビゲーションには未掲載です。改訂履歴：v0.1（2026-07-28、公式ランクの影響を受ける）；v0.2（2026-07-29、公式ランクから離脱）；v0.3（2026-07-29、副本/ボスと編成リレーを統合）。完全な推論は <code>llm_reco/reasoning-log.md</code> と <code>reco-team.md</code> を参照。</em></p>`,46)])])}const p=d(e,[["render",n]]);export{b as __pageData,p as default};
